settings.air_reviews_json_ld_v2:
{% assign productTitle = product.title | default: '' %}{% assign productDesc = product.description | default: '' | escape | truncate: 150 %}{% assign productImage = product.featured_image | default: '' %}{% assign ratingValue = product.metafields.reviews.rating.value.rating | default: product.metafields.air_reviews_product.review_avg | default: 0 %}{% assign bestRating = product.metafields.reviews.rating.value.scale_max | default: 5 %}{% assign reviewCount = product.metafields.air_reviews_product.review_count | default: 0 %}{% assign worstRating = product.metafields.reviews.rating.value.scale_min | default: 1 %}{
"@context": "http://schema.org",
"@type": "Product",
"name": "{{ productTitle | escape }}",
"description": "{{ productDesc | escape }}",
"image": "{{ productImage | escape }}",
"aggregateRating": {
  "@type": "AggregateRating",
  "ratingValue": {{ ratingValue }},
  "bestRating": {{ bestRating }},
  "reviewCount": {{ reviewCount }}
 }{% if shop.metafields.air_reviews_has_ugc_content.data.value == true and product.metafields.air_reviews_product.data.value.reviews %}, 
  "review":[{% assign reviewsData = product.metafields.air_reviews_product.data.value.reviews %}
  {% for review in reviewsData limit: 10 %}
    {
      "@type": "Review",
      "author": {
        "@type": "Person",
        "name": "{% if review.firstName %}{{ review.firstName | escape }}{% elsif review.lastName %}{{ review.lastName | escape }}{% else %}Anonymous{% endif %}"
      },
      "reviewRating": {
          "@type": "Rating",
          "bestRating": {{ bestRating }},
          "ratingValue": {{ review.rate | default: 0 }},
          "worstRating": {{ worstRating }}
      },
      "reviewBody": "{{ review.content | default: '' | escape }}",
      "datePublished": "{{ review.createdAt | date: '%Y-%m-%d' }}"
    }{% unless forloop.last %},{% endunless %} 
  {% endfor %}]{% endif %}
}
